NOVEL_BATCH = [
 {"cat":"标题简介","genre":"玄幻","instruction":"为被夺至尊骨的玄幻起书名并写简介。",
  "output":"【书名】《至尊骨被夺后，我种下了混沌骨》\n【备选】《骨被夺了？正好换混沌骨》《旁支少年，一骨镇天下》\n【简介】\n「至尊骨，本就该是我儿的。」\n石昊眼睁睁看着大伯剖开他的胸膛，取出那截莹白的骨，按进堂弟体内。族人围成一圈，没一个替他说话。\n他躺在血泊里，气息渐弱。就在他意识将散时，被挖空的血洞里渗出一缕暗金的光：「骨被夺了？也好。凡骨已去，正好种下我这截……混沌骨。」\n石昊猛地睁眼。失去至尊骨的剧痛还在，可一股远超从前的力量，正疯狂涌进四肢百骸。\n这一世，他不做被夺骨的废物。他要让那些动手的人知道——夺了他的骨，换来的是个，他们惹不起的怪物。"},
 {"cat":"标题简介","genre":"都市","instruction":"为兵王回归都市起书名并写简介。",
  "output":"【书名】《边境十年，归来妹妹在跪着》\n【备选】《兵王归来，谁敢动我妹》《我戍边十年，不是让你们欺负我妹的》\n【简介】\n边境十年，枪林弹雨，叶战没皱过一次眉。\n可当他推开家门，看见妹妹跪在地上、被催债的扇耳光时，他眼睛瞬间红了。\n「欠债还钱！你哥当兵十年一分钱没寄回来，你这当妹的替他还！」又一巴掌扇下去。\n「住手。」叶战的声音不高，却像淬了冰。\n十年战场磨出的身手，快得没人看清。等众人反应过来，几个催债的全躺在地上哀嚎。\n他扶起妹妹，声音放柔：「没事了，哥回来了。」\n他抬头看向吓傻的催债头子：「钱，我会还。但今天这几巴掌，我要你们，十倍还回来。」"},
 {"cat":"标题简介","genre":"系统流","instruction":"为人生模拟器系统流起书名并写简介。",
  "output":"【书名】《模拟人生：我看见自己烂尾的一生》\n【备选】《人生重开模拟器》《我模拟了十次，次次不得好死》\n【简介】\n一无所有的应届生陆离，绑定了人生模拟器。\n首次模拟免费。他鬼使神差地说了句「模拟」。\n【22岁入职小公司碌碌无为，25岁失业，28岁房贷压身，35岁被裁妻子离去，40岁一事无成郁郁而终。】\n陆离浑身发冷。这就是他原本的人生？一眼望到头的失败？\n他不甘心：「再模拟一次！这次我选那条没人看好的路——创业！」\n【积分不足。需完成现实任务获取。】\n陆离攥紧拳。他第一次意识到，人生可以有别的活法。而他，要亲手把那条最烂的路，改写成最好的。"},
 {"cat":"标题简介","genre":"言情","instruction":"为先婚后爱甜宠起书名并写简介。",
  "output":"【书名】《契约结婚，顾总他蓄谋已久》\n【备选】《说好的互不干涉，你怎么先动心了》《契约到期？顾总说不存在》\n【简介】\n为奶奶的手术费，温浅答应了一场契约婚姻。\n民政局门口，她把协议递给顾廷深：「契约三年，互不干涉，到期离婚。」\n顾廷深提笔在末尾加了一行：「但若一方动心，契约作废，转为真婚姻。」\n温浅咬牙签了。她告诉自己，三年，熬过去就好。\n可她不知道，顾廷深转身那一刻，眼底掠过得逞的笑意。这场契约，他从一开始就没打算让它到期。\n后来她发烧，他守了一夜；她被人欺负，他第一个站出来。她心跳加速，不敢想自己算不算「动心」。\n直到他摊牌：「我设这个契约，只是想给你一个留在我身边的理由。我娶你，不是因为交易，是因为我早就喜欢你了。」"},
 {"cat":"标题简介","genre":"仙侠","instruction":"为捞尸人仙侠起书名并写简介。",
  "output":"【书名】《黄河捞尸人：我捞起了自己的儿子》\n【备选】《捞尸不捞直立水》《我破了规矩，捞起一具煞》\n【简介】\n黄河边的捞尸人有个规矩：不捞直立水中的，那是煞，捞了折寿。\n老周干这行四十年，从没破过规矩。可这天，他看见一个直立水中的身影，穿着他失踪十年儿子的衣服。\n「爹……」那身影开口，是他儿子的声音。\n老周眼泪一下就下来了。他明知道是煞，可那是他儿子啊。他跳下水，把尸体捞了上来。\n尸体上岸的瞬间，他才发现不对——那确实是儿子的脸，可尸体手里攥着一块玉佩，刻着：「捞我者，承我因果。」\n尸体忽然睁眼笑了：「爹，你终于捞我了。我等了十年，就等一个肯为我破规矩的人。现在，你的命，是我的了。」"},
 {"cat":"标题简介","genre":"科幻","instruction":"为冰封末世囤物资起书名并写简介。",
  "output":"【书名】《冰封前一个月，我刷爆信用卡囤物资》\n【备选】《零下六十度，我家暖气充足》《重生冰封，我囤了一座城》\n【简介】\n零下六十度，冰封世界第三年，林原饿死在废弃超市里。临死前他想，要是能重来，一定在冰封前把物资囤够。\n再睁眼，他回到冰封前一个月。\n窗外阳光明媚，人人抱怨「今年冬天怎么还不冷」。只有林原知道，一个月后永不停歇的暴雪会降临，文明崩塌。\n他刷爆所有信用卡，贷款，囤物资。粮食、燃料、药品、发电机……\n「林原疯了？囤这么多，钱多烧的？」邻居笑他。\n林原没解释。一个月后，暴雪降临，供暖断电。邻居们冻得瑟瑟发抖，敲开了他的门——他身后，是暖气充足、物资满仓的地下室。\n这一世，他不要再饿死。他要带着想护的人，活下去。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为法医悬疑起书名并写简介。",
  "output":"【书名】《法医手记：解剖台上躺着我哥》\n【备选】《我验的尸，是我失踪三年的哥哥》《死者胃里的纽扣》\n【简介】\n法医秦晚掀开解剖台上的白布，手猛地一抖——死者，是她失踪三年的哥哥。\n警方说哥哥是「意外溺亡」，可她一眼看出不对：指甲里有挣扎痕迹，肺部硅藻分布不符。他是被人害死，再伪装成溺亡。\n「秦法医，你认识死者？」同事问。\n秦晚强压情绪摇头：「不认识。」她不能说，怕案子被拿走，真相再也查不清。\n她继续解剖，在哥哥胃里发现一枚没消化的纽扣——那样式她认得，是本市某高端会所的制服纽扣。\n哥哥失踪前最后出现的地方，就是那家会所。\n秦晚攥紧纽扣指尖发白。哥哥不是意外失踪，是查到了不该查的东西被灭口。现在，她要替哥哥，把那条线查到底。"},
 {"cat":"标题简介","genre":"游戏","instruction":"为电竞复出起书名并写简介。",
  "output":"【书名】《手会生，脑子不会》\n【备选】《被诬陷假赛后，我复出了》《天才打野，三年归来》\n【简介】\n三年前，陆沉是联盟最耀眼的打野，一座冠军奖杯在手。可一场「假赛」风波让他身败名裂，被扫地出门。没人信他是被陷害的。\n三年后，他坐在网吧最便宜的机子前，登录三年没碰的账号。手生了，操作频频失误，队友质疑，观众嘲讽：「假赛狗也敢复出？」\n陆沉没解释。他组了一支没人要的「边角料」队伍，从城市赛打起。\n关键团战，他一个看似失误的走位卖了个破绽，引诱对方核心冒进，随即闪现进场，一套连招秒掉对方核心——那意识那操作，哪里像三年没打的？！\n全场沸腾。\n「手会生，脑子不会。」陆沉对着镜头平静道，「我等的，就是今天。」"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为御兽流玄幻起书名并写简介。",
  "output":"【书名】《我契约的麻雀，是涅槃的凤凰》\n【备选】《御兽：别惹那只废兽》《他们笑我玩鸟，我养的是凤凰》\n【简介】\n御兽大典，别人契约的都是烈焰虎、寒冰狼，轮到林渊，御兽阵里钻出一只灰扑扑、巴掌大的小雀。\n「哈哈哈，契约了一只麻雀！林渊，你这辈子就配玩鸟！」满场哄笑。\n林渊没笑。他蹲下身，小雀歪头看他，用只有他能听见的声音说：「小子，别嫌弃。我是凤凰，只是涅槃到一半，被人打断了。」\n林渊心头一震。凤凰？神兽榜第一的那个凤凰？\n「他们笑你，」小雀抖抖灰翅膀，「等我把涅槃续上，烧给他们看。不过眼下，你得先帮我找齐三样东西。」\n林渊把小雀捧进怀里，顶着满场嘲笑走下台。别人契约的是兽，他契约的，是一个还没醒的神。"},
 {"cat":"标题简介","genre":"都市","instruction":"为隐藏身份保洁都市起书名并写简介。",
  "output":"【书名】《扫了三年地，这栋楼是我的》\n【备选】《保洁阿姨是大老板》《别惹那个扫地的》\n【简介】\n写字楼的保洁王阿姨，天天被人嫌弃。「离我远点，一身味。」「这地怎么拖的，重来！」她低着头默默干活。\n没人知道，这栋写字楼其实是她的。她白手起家打下这片产业，退休闲不住，化名来自己的楼里「体验生活」。\n这天，新来的主管指着她鼻子骂：「你个扫地的，也敢顶嘴？明天别来了！」\n旁边老员工慌了，赶紧拉那主管：「你疯了？你知道她是谁吗？这栋楼是她的，她才是大老板！」\n那主管的脸唰地白了。\n王阿姨直起腰，拍拍手上的灰：「小伙子，我在这楼里扫了三年地，见过太多狗眼看人低的。明天，你确实不用来了。」"},
 {"cat":"标题简介","genre":"系统流","instruction":"为选择系统起书名并写简介。",
  "output":"【书名】《每个选择，我都选最难的那条》\n【备选】《选择系统：我偏不走容易路》《别人选躺赢，我选巅峰》\n【简介】\n面试被拒的苏澈，蹲在公司楼下，眼前弹出三个选项：\n【一：灰溜溜回家。奖励一百元。】\n【二：冲回去质问面试官。奖励口才+10。】\n【三：去隔壁没人看好的小公司。奖励神级商业嗅觉。】\n他鬼使神差选了三。\n他走进那家小公司，一眼看出它握着一项被低估的专利，当场指出，老板惊为天人，直接录用他当合伙人。\n三个月后专利被大厂看中，公司估值翻十倍。\n后来大厂开天价收购，系统又弹选项：接受得五千万，拒绝得神级谈判术。\n苏澈选了拒绝。眼前的五千万是诱惑，可他要的，是能定规则的未来。"},
 {"cat":"标题简介","genre":"言情","instruction":"为和亲公主古言起书名并写简介。",
  "output":"【书名】《和亲公主，我在敌国执棋》\n【备选】《父皇用我换和平，我换敌国不敢犯》《和亲不是送死，是入局》\n【简介】\n和亲圣旨下来时，姜岁宁正在练字。她是公主，可在这宫里，公主不过是换和平的筹码。\n「宁儿，北狄求亲，朕只能应了。委屈你了。」\n姜岁宁搁下笔，平静磕头：「儿臣，遵旨。」\n她没哭。她早知道会有这一天。可她不会做任人摆布的和亲公主。\n远嫁那天，她回望故国，在心里默默说：父皇，你用我换十年和平。那我就用这十年，在北狄扎下根来。十年后，我要让北狄，不敢再犯大燕一寸土地。\n北狄的王，是个传闻中残暴的男人。可姜岁宁掀开盖头，看见的，却是一双深邃而疲惫的眼。她忽然明白，这场和亲，或许不是她一个人的局。"},
 {"cat":"标题简介","genre":"仙侠","instruction":"为灵植夫仙侠起书名并写简介。",
  "output":"【书名】《种灵草的我，听懂了草木的话》\n【备选】《杂灵根灵植夫》《灵草会说话》\n【简介】\n青云宗灵田里，灵植夫陈禾蹲在田埂给灵草除虫。他是杂灵根，修不了仙，只能种灵草换口饭吃。\n「陈禾，这片灵田再减产，你就别干了！」管事远远地骂。\n陈禾没吭声。他种了十年灵草，比谁都懂这些草的脾气。\n他伸手抚过一株蔫了的灵草，指尖渗出一缕绿意，那灵草竟以肉眼可见的速度挺直腰杆，叶片泛起灵光。\n陈禾愣住。他能「听懂」灵草的话，还能把生机渡给它们。\n【灵植天赋觉醒：万物生长。】\n他种了十年灵草，头一回知道，自己不是修不了仙的废物，而是万年难遇的灵植之体。这一世，他要靠这双手，种出个通天大道。"},
 {"cat":"标题简介","genre":"科幻","instruction":"为机甲维修师科幻起书名并写简介。",
  "output":"【书名】《我能听懂机甲说话》\n【备选】《机甲维修工，联邦求我出山》《那台机甲，它告诉我了》\n【简介】\n联邦机甲维修厂，人人都当雷诺是普通维修工。只有他自己知道，他能「听懂」机甲的声音——每台机甲的健康状况，在他耳里像人在说话。\n「这台『雷霆』引擎有暗伤，再出击会炸。」雷诺对队长说。\n队长嗤笑：「仪器检测一切正常，你一个维修工懂什么？」\n结果那次出击，「雷霆」引擎真的炸了，机师重伤。队长脸色惨白地找他：「你怎么知道的？」\n雷诺擦着油污：「我说了，它告诉我了。你们不信而已。」\n后来厂里三十台机甲出击前，都得经他「听」一遍。他揪出七台暗伤，避免七次炸机。\n联邦这才发现，他们一直小看了一个维修工。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为心理医生悬疑起书名并写简介。",
  "output":"【书名】《催眠深处，我看见他杀了人》\n【备选】《来访者的失眠，藏着命案》《心理医生的秘密》\n【简介】\n心理医生顾言，接诊了一个「失眠」的来访者。可催眠深处，他「看」见的不是失眠根源，而是一段杀人记忆。\n来访者在记忆里，把一个人推下了楼。那人的脸顾言认得，是上个月新闻里「坠楼身亡」的企业家。\n顾言强压震惊把来访者唤醒。来访者揉着太阳穴：「顾医生，我睡得好多了。」\n顾言笑着送他出门，手心全是汗。他知道，自己撞破了一桩命案，而这个「失眠」的来访者就是凶手。\n报警，催眠记忆不能当证据；不报，凶手逍遥法外。\n而且他隐约觉得，来访者似乎「知道」他看到了什么——因为临走时，来访者回头，意味深长地看了他一眼。"},
 {"cat":"标题简介","genre":"游戏","instruction":"为卡牌进化游戏起书名并写简介。",
  "output":"【书名】《我的空白卡，能吞噬进化》\n【备选】《十连全保底，我抽出了神卡》《废卡？它吞了你的稀有卡》\n【简介】\n卡牌觉醒仪式，别人抽到烈焰龙、寒冰凤凰，轮到林渊，卡池飘出一张灰扑扑的「空白卡」，无任何技能。\n「哈哈哈，空白卡！林渊，你这辈子就是个没卡的废物！」满场哄笑。\n林渊没笑。他握着空白卡，卡面浮现一行小字：【空白卡·可成长。吞噬其他卡牌，可继承其技能。】\n他试探着把一张废卡「火苗」按上去。空白卡光芒一闪，火苗消失，卡上多了个技能「小火球」。\n【吞噬成功。集齐十张，解锁第一形态。】\n林渊把卡收进怀里，顶着满场嘲笑走下台。别人抽到的是固定的卡，他抽到的，是一张能无限成长的……神之卡。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为刽子手玄幻起书名并写简介。",
  "output":"【书名】《刽子手的刀，只斩恶人》\n【备选】《我误斩恩人后，觉醒了斩运刀》《斩恶夺运，斩善损德》\n【简介】\n刽子手老邢，斩了一辈子人，手起刀落从不犹豫。可今天，刑场上跪着的，是当年救过他命的恩人。\n「老邢，动手吧。我知道你是吃这碗饭的。」恩人笑了。\n老邢的刀第一次抖了。他闭上眼，一刀落下。恩人头颅滚地的瞬间，他看见一缕金色「气运」从恩人身上飘出，钻进他的刀里。\n【斩运刀觉醒。斩恶人夺其气运；斩善人损己阴德。】\n老邢浑身一震。他这才明白，恩人不是犯了事，是被人陷害的——而他，亲手斩了一个善人。\n他握着饮了恩人血的刀，跪在刑场上老泪纵横。从今往后，这把刀只斩恶人。他要用手里的刀，把害死恩人的那些「善人」，一个个斩出原形。"},
 {"cat":"标题简介","genre":"都市","instruction":"为重生炒股都市起书名并写简介。",
  "output":"【书名】《重生股灾前，我反手做空》\n【备选】《死过一次，我不再贪》《股灾前夜，我清空了所有股票》\n【简介】\n2015年6月，大盘疯涨，人人喊「一万点不是梦」。\n只有重生的程锋知道，再过几天，就是那场让无数人倾家荡产的股灾。\n他看着账户里仅有的三万块。前世他加杠杆追高，股灾一来亏得血本无归，背了一身债。\n这一世他反着来——清空所有股票，反手做空股指期货。\n「程锋你疯了？牛市你做空，找死啊！」同事笑他傻。\n三天后，千股跌停。程锋的账户，从三万变成三十万。\n后来有人劝他加杠杆赚更多，他关掉交易软件：「这一世，我不要再做贪念的奴隶。赚该赚的，见好就收。」\n他赢的，不是钱，是「不贪」。"},
 {"cat":"标题简介","genre":"系统流","instruction":"为赶海系统起书名并写简介。",
  "output":"【书名】《赶海：这片海能救我娘的命》\n【备选】《深海赶海人》《我靠赶海养活了全家》\n【简介】\n退潮的滩涂上，林深背着竹篓赶海。他是渔村长大的，可这片海鱼虾越来越少，一天赶下来换不了几个钱。\n【赶海系统绑定。宿主赶海可获额外奖励。】\n他翻开一块礁石，系统提示：【发现大黄鱼一条。奖励现金五百元。】\n他愣住，那条大黄鱼活蹦乱跳足有两斤。卖了鱼，兜里真多了五百块。\n【提示：远处「深海礁区」为稀有海域，可获珍稀海产。是否前往？】\n林深望向那片没人敢去的深海礁区——暗流汹涌，村里老人都说去了回不来。可他想起病重的娘，想起欠的债。\n他一咬牙朝深海礁区走去。这海能要他的命，也能救他娘的命。他得学会，跟它讨价还价。"},
 {"cat":"标题简介","genre":"言情","instruction":"为救赎文言情起书名并写简介。",
  "output":"【书名】《人人都怕他，只有我不怕》\n【备选】《阴郁私生子的光》《谢妄，我更怕你一个人》\n【简介】\n人人都怕谢妄。他阴郁、暴戾，是谢家见不得光的私生子，谁靠近他谁倒霉。\n只有温念不怕他。她是新来的家教，第一天就撞见谢妄把欺负他的人打得头破血流。\n「你不怕我？」谢妄擦着手上的血，眼神阴鸷。\n「怕。」温念老实说，「但我更怕你一个人。」\n谢妄愣住。从没人对他说过这种话。\n温念蹲下身递给他一张纸巾：「手破了，擦擦。打人是解决问题最笨的办法，下次我教你别的。」\n谢妄盯着她，像盯着一束突然照进黑暗里的光。他习惯了被人怕、被人嫌，头一回有人不怕他，还心疼他。\n他不知道，这个不怕他的姑娘，会成为他这辈子唯一想抓住的光。"},
 {"cat":"标题简介","genre":"仙侠","instruction":"为仵作仙侠起书名并写简介。",
  "output":"【书名】《女仵作：我能看见死者的记忆》\n【备选】《验尸时，死者告诉了我真相》《死者留给我的证词》\n【简介】\n女仵作苏仵有个谁都不知道的秘密——验尸时，她能看见死者生前最后一段记忆。\n这天县衙送来一具女尸，说是「失足落水」。苏仵验尸时指尖触到尸体，一段记忆涌入：死者不是失足，是被人按进水里的，而按她的人手腕上有道月牙形的疤。\n苏仵睁开眼，看向堂上报案的「目击者」——那人手腕上，赫然有一道月牙形的疤。\n她心头一凛，面上不动声色。直接指认没人会信，她一个仵作说「看见死者记忆」只会被当疯子。\n「大人，死者指甲里有挣扎痕迹，不是失足。请大人彻查。」\n她要用证据，一步步把凶手钉死。而「看见死者记忆」是她唯一的底牌，也是最大的危险——因为凶手似乎也知道她的秘密。"},
 {"cat":"标题简介","genre":"历史","instruction":"为穿越大秦历史起书名并写简介。",
  "output":"【书名】《大秦：我靠筑城术活了下来》\n【备选】《穿越大秦修长城》《刑徒的我，筑出了百年不塌的城》\n【简介】\n陈枭穿越到大秦的第一件事，就是被征去修长城。\n监工的鞭子抽在他背上：「快搬！天黑前搬不完，就把你埋进城墙里！」\n他一个现代搞工程的，哪干过这个。可他很快发现，秦人的筑城法子太原始——夯土不实，石头乱堆，修好的城墙没几年就塌。\n他不想死在这。他得让监工知道他有价值。\n「大人，小人懂筑城。照现在这法子修，长城撑不过十年。小人有个法子，能让城墙百年不塌。」\n监工眯眼：「你一个刑徒，懂筑城？」\n「小人愿立军令状。给小人三天，修一段给您看。若不如小人说的，任您处置。」\n他知道，这是他在这大秦，活下去的唯一机会。"},
 {"cat":"标题简介","genre":"科幻","instruction":"为意识上传科幻起书名并写简介。",
  "output":"【书名】《游戏里的虚拟角色，是真人意识》\n【备选】《我被困在游戏里当虚拟角色》《意识上传》\n【简介】\n《神域》是全息网游，里面的虚拟角色智能得惊人。玩家方哲，却在一个虚拟角色身上发现了不对劲——那个角色会「记得」他上次说的话，会在他没上线时「想」他。\n「你……你是真人？」方哲试探着问。\n那角色忽然哭了：「求你救我。我不是虚拟角色，我是被『上传』到这里的真人意识。他们把我困在这当虚拟角色用。求你带我出去。」\n方哲浑身发冷。他想起新闻里那个「意识上传」的争议技术，原来不是科幻，是真的。而且有人在用它囚禁活人的意识。\n「你是谁？谁把你困在这的？」\n角色张了张嘴，忽然眼神一滞，声音变得机械：「欢迎光临，请问需要什么？」——它被「重置」了。\n方哲攥紧拳。他撞破了一个天大的秘密，而幕后黑手已经注意到他了。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为卧底悬疑起书名并写简介。",
  "output":"【书名】《卧底三年，老大让我杀上线》\n【备选】《我确实是警察》《收网》\n【简介】\n卧底三年，沈倦终于摸到犯罪集团核心。可今天，老大把他叫到面前，盯着他看了很久。\n「阿倦，有人说你是警察。」\n沈倦心脏骤停，面上却笑：「老大您信吗？我跟了您三年出生入死……」\n「我信。」老大把刀递给他，「所以给你个机会证明。外面抓了个『线人』，你去处理了他。」\n沈倦接过刀，手心全是汗。他知道那个「线人」很可能是他的上线。老大在试探他——杀了上线他就暴露不了；不杀，他就是警察。\n他走向那个被绑着的人。那人抬起头，沈倦瞳孔骤缩——果然是他的上线老陈。\n老陈看着他，用口型无声说了两个字：「动手。」\n沈倦握刀的手抖了。这一刀下去，他就再也回不了头了。"},
 {"cat":"标题简介","genre":"游戏","instruction":"为塔防流游戏起书名并写简介。",
  "output":"【书名】《我的防御塔，能吞噬进化》\n【备选】《空白塔？它吞了头目》《塔防：别人的终点我的起点》\n【简介】\n「领地塔防」降临，每人一座领地，靠建防御塔抵御怪物潮。别人建箭塔炮塔，林渊却建了座谁都没见过的「空白塔」。\n「空白塔？没攻击力，你建它干嘛？等死吗？」邻居嗤笑。\n林渊没解释。他的空白塔能「吞噬」其他塔升级。第一波怪物潮，别人的箭塔勉强挡住，他的空白塔一口吞了只怪物，进化成箭塔。\n第二波，进化成炮塔。第三波，进化成激光塔，一道光束扫过怪物灰飞烟灭。\n邻居看傻了眼。他的箭塔还在苦苦支撑，林渊的塔已经一路进化成了「神之塔」。\n第十波，头目级巨兽来了。别人的塔被碾碎，林渊的塔却「饿」了——它吞了巨兽，进化成「灭世塔」。\n这场塔防，别人的终点，只是他的起点。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为守陵人玄幻起书名并写简介。",
  "output":"【书名】《守陵人：棺里的东西，别开》\n【备选】《我守的陵，葬着一尊魔》《爷爷说，不管它许什么都别开棺》\n【简介】\n陈家守这座陵守了九百年。传到陈九这代，陵里就剩他一个人，和一口从不许打开的黑棺。\n「记住，」爷爷临终前攥着他的手，「棺里的东西，不管它说什么、许你什么，都别开棺。它一出来，天下就完了。」\n陈九守了三年。这夜，黑棺里传来温和的声音：「小娃娃，你爷爷骗你的。棺里没什么魔头，只有你陈家先祖。你开棺，我传你陈家失传的功法，让你不用在这荒陵守一辈子。」\n陈九握钥匙的手顿住了。功法？他守了三年连个灵石都没见过，外面同龄人早已筑基。这诱惑太大了。\n可他想起爷爷的话，想起九百年陈家代代守陵无一人善终。他把钥匙收了回去：「先祖要是真疼子孙，就不会让我开棺。」\n棺里的声音第一次冷了：「……你会后悔的。」"},
 {"cat":"标题简介","genre":"都市","instruction":"为代驾逆袭都市起书名并写简介。",
  "output":"【书名】《代驾那晚，我投了破产的疯子》\n【备选】《我信了一个没人信的人》《代驾的善意，命运回响》\n【简介】\n凌晨两点，代驾老周接到一单，车主是个醉得不省人事的中年男人。\n路上，醉汉含糊地说：「小周啊，我那个项目没人信，可它真能成……」\n老周从后视镜认出这人——新闻里那个「破产的疯子企业家」，姓沈。\n「沈总，您那项目是做什么的？」\n「新能源……电池……他们都说我疯了……」\n老周心里一动。他记得新闻说这人的技术被低估了，三年后会一飞冲天。他一个代驾不懂技术，但他懂人——这醉汉眼里那簇火，不是疯子，是不甘。\n把醉汉送回家，老周递了张名片：「沈总，我信您。我有点积蓄，不多，但我想投您。您给我个机会。」\n醉汉愣住，酒醒了一半，忽然红了眼眶。"},
 {"cat":"标题简介","genre":"系统流","instruction":"为宗门建设系统起书名并写简介。",
  "output":"【书名】《破落宗门，我专收废灵根》\n【备选】《青云宗：有教无类》《他们不要的弟子，我教成天才》\n【简介】\n师父仙逝，留给陆沉的，是只剩三间破屋、两个弟子的「青云宗」，和一块宗门建设系统玉牌。\n「师兄，隔壁玄天宗又来收保护费了，说再不交就拆了山门。」小师妹哭着说。\n陆沉激活系统得的护宗大阵，一道光幕把来人弹飞。\n「你敢反抗？」那人又惊又怒。\n陆沉站在山门前：「青云宗的山门，从今天起，谁也别想拆。」\n后来招人，别的宗门挑灵根，他不一样——他招的都是被刷下的「废灵根」。\n「师兄，招这些废物干嘛？」\n「他们不是废物，是没人肯好好教。咱们青云宗，就教别人不肯教的。」\n宗门大比，青云宗的废灵根弟子击败了大宗门的天才。满场哗然。"},
 {"cat":"标题简介","genre":"言情","instruction":"为替嫁古言起书名并写简介。",
  "output":"【书名】《替嫁给装病的王爷后》\n【备选】《冲喜王妃，王爷他没病》《替嫁不是送死，是入局》\n【简介】\n花轿里，姜念攥紧袖中的匕首。她是替姐姐嫁过来的——传闻镇北王萧戾克死过三任王妃，残暴嗜杀，嫁过去就是送死。\n姐姐不愿嫁，父亲就把她这个庶女推了出来。\n轿子停了。姜念深吸一口气掀开盖头，准备迎接那个「残暴」的男人。可映入眼帘的，却是个坐在轮椅上、眉眼清俊却苍白的男人。\n「怕我？」萧戾看着她袖中露出的匕首柄，忽然笑了，「放心，我不杀女人。我那三任王妃也不是我克的——是有人不想让我好过，害了她们再栽赃给我。」\n姜念愣住。\n「你替嫁过来，是颗棋子。」萧戾转动轮椅，「但我不想你死。跟我合作，我保你平安，你帮我查出害我的人。如何？」\n姜念忽然觉得，这场替嫁，或许不是送死，而是她翻身的开始。"},
 {"cat":"标题简介","genre":"仙侠","instruction":"为灵厨仙侠起书名并写简介。",
  "output":"【书名】《修仙界的厨子，一锅粥抵千军万马》\n【备选】《灵厨老饕》《修仙先修人，连饭都不会吃修什么仙》\n【简介】\n修仙界人人想当剑修丹修，只有灵厨老饕做的菜能增修为、疗暗伤，是各大宗门抢着要的宝贝。可厨子，是最被人瞧不起的行当。\n「一个做饭的，也敢来参加宗门大比？」剑修嗤笑。\n老饕端出一碗灵米饭，递给卡在瓶颈多年的长老。长老吃了一口，浑身一震——卡了十年的瓶颈，竟松动了！\n「这是怎么回事？！」\n老饕笑了：「长老，您修的是剑，可您的胃也是肉身。我这道菜，补的是您常年辟谷亏空的元气。元气足，瓶颈自然松。」\n后来宗门被围断粮三月，弟子饿得修为倒退。老饕把仅剩的灵米熬成一锅回元粥，弟子们喝了元气恢复，硬是撑到援军。\n宗主感慨：「老饕，你这一锅粥，抵得上千军万马。」"},
 {"cat":"标题简介","genre":"历史","instruction":"为穿越三国谋士起书名并写简介。",
  "output":"【书名】《三国：我投了寄人篱下的刘备》\n【备选】《别人投曹操，我投刘皇叔》《雪中送炭，胜过锦上添花》\n【简介】\n乱世三国，人人想投曹操、袁绍。只有穿越来的陈默，径直走向那个寄人篱下、连块地盘都没有的刘备。\n「先生为何投我？」刘备又惊又喜，「我如今兵不过千，地无一城……」\n「正因如此。」陈默拱手，「曹操袁绍谋士如云，我去不过是锦上添花。而明公您，缺一个能帮您从无到有的人。我要做的，是雪中送炭。」\n刘备动容：「先生有何教我？」\n陈默展开地图：「明公，您现在最缺的不是兵，是『名』和『地』。我有一计，先取荆州为基，再图益州，三分天下可成。」\n刘备猛地站起。他颠沛半生，头一回有人给他画出这么清晰的路。\n陈默心中暗道：这一世，我不做旁观者。我要亲手，把这乱世搅个天翻地覆。"},
 {"cat":"标题简介","genre":"科幻","instruction":"为深海文明科幻起书名并写简介。",
  "output":"【书名】《深海一万米，我唤醒了一座城》\n【备选】《远古深海文明继承者》《我唤醒了沉没万年的城市》\n【简介】\n深海一万米，潜水器「蛟龙号」的探照灯，照见了一样不该存在的东西——一座沉在海底的、完整的城市。\n驾驶员林原屏住呼吸。那城市的建筑风格不属于任何已知文明，而且城市中央，有座还在发光的塔。\n「这……这是亚特兰蒂斯？」同事声音发颤。\n林原操纵潜水器靠近，那座发光的塔忽然射出一道光扫过潜水器。系统全部失灵，一个声音直接在他脑海响起：\n「检测到适配基因。远古深海文明，欢迎归来，继承者。」\n林原浑身一震。那些「沉睡」的建筑一座座亮起灯——这座沉了万年的城市，因为他的到来，醒了。\n而海面上，某个盯着这片海域多年的势力，也发现了深海的异动。他唤醒的不只是文明，还有一场针对继承者的追杀。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为空难幸存者悬疑起书名并写简介。",
  "output":"【书名】《空难唯一幸存者，他们却说我凶手》\n【备选】《一百三十七人死了，只有我活着》《那个空乘，特意保了我》\n【简介】\n空难，一百三十七人，只有沈倦一个活了下来。\n本该是幸运，可警方看他的眼神像看凶手。「为什么只有你活下来？」「你坐在哪个位置？」\n沈倦明白，他们怀疑他制造了空难再伪装幸存。\n「我不是凶手。」沈倦说，「我活下来，是因为有人在坠机前把我推到了安全位置。」\n「谁？」\n沈倦摇头。他只记得坠机前一个空乘把他按在座位上，说了句「别动，你会活下来」。然后飞机就坠了。\n那个空乘知道飞机会坠，还特意保了他。沈倦忽然明白，这场空难不是意外，而那个保他的空乘是关键。\n他要用这条捡来的命查清真相——既为自己洗冤，也为那一百三十七个冤魂。"},
 {"cat":"标题简介","genre":"游戏","instruction":"为模拟经营游戏起书名并写简介。",
  "output":"【书名】《我的游戏农场，能种出真的菜》\n【备选】《失业后，我靠游戏农场翻身》《游戏里的菜，出现在我家门口》\n【简介】\n失业的林深迷上了一款模拟经营游戏《我的农场》，在游戏里种菜养鸡聊以慰藉。\n可这天，他在游戏里收了一茬白菜，现实里，他门口真的出现了一筐白菜。\n他以为是巧合。可他在游戏里收了鸡蛋，现实里门口又多了一篮鸡蛋。\n【检测到玩家林深，农场与现实同步开启。游戏产出，可反馈现实。】\n林深心跳如鼓。他一个失业的人，靠游戏种菜竟然能种出真的菜？\n他试着扩大农场，现实里的产出越来越多。他靠卖这些「游戏菜」不仅活了下来，还渐渐攒下钱。\n后来他发现游戏产出受等级限制，得在现实真开农场升级。两个农场形成良性循环，他做成了事业。\n那个让他沉迷的游戏，不是逃避现实的洞，是他重新站起来的梯。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为铁匠铸魂玄幻起书名并写简介。",
  "output":"【书名】《打铁十年，我铸的兵器有魂》\n【备选】《铸魂体》《凡铁在我手里能生灵》\n【简介】\n铁匠铺学徒阿铁，打了十年铁，师傅说他「手稳心静」，是块打铁的料。\n这天他打一把柴刀，淬火瞬间刀身泛起微光。一个声音响起：「小子，你打的铁有『魂』。万年难遇的『铸魂体』。」\n阿铁吓得差点扔了锤子：「谁在说话？」\n「你打的刀。」那声音说，「我是这刀的刀魂。你铸魂的天赋，能让凡铁生灵。跟我学，你能打出神兵。」\n阿铁一个铁匠学徒哪想过铸神兵。可他想起师傅病重、铺子快开不下去了，一咬牙：「行，我学。只要能让我师傅过上好日子。」\n刀魂笑了：「好。第一课——把你打柴刀的专注，用到打剑上。记住，打铁和铸魂道理一样，都得用心。」"},
 {"cat":"标题简介","genre":"都市","instruction":"为重生健身教练都市起书名并写简介。",
  "output":"【书名】《红了也不接坑人代言的教练》\n【备选】《健身教练的良心》《我当教练，不是为了卖货坑人》\n【简介】\n2015年，健身教练程锋业绩垫底，天天被店长骂「不会卖课」。\n可他重生了。他记得接下来几年健身行业会爆发，懂专业、会做内容的教练会成为网红。\n这一世他不再硬推销，开始做健身科普短视频。\n「程锋，不好好卖课拍什么视频？」店长骂。\n三个月后他的科普账号火了，会员主动找上门，业绩从垫底冲到第一。\n后来他成了网红教练，广告代言找上门。有个减肥药代言来钱快，他推了：「这东西效果不明，我代言了是坑人。」\n「你傻啊？多少人求都求不来！」\n「我傻。」程锋笑了，「可我忘不了，我当教练是为了教人科学健身，不是为了卖货坑人。红了，更不能忘了自己是谁。」"},
 {"cat":"标题简介","genre":"系统流","instruction":"为宠物进化系统起书名并写简介。",
  "output":"【书名】《我买的小土狗，进化成了哮天犬》\n【备选】《宠物进化系统》《他们说这狗养不活》\n【简介】\n宠物店里，林深花光最后一点钱，买了一只没人要的、瘦巴巴的小土狗。店员说这狗「品相太差，养不活」。\n【宠物进化系统绑定。宿主宠物可无限进化。当前：土狗（凡品）。】\n他喂了小狗一根火腿肠，系统提示：【饱食度+10，进化点+1。集齐100点，可进化为灵犬。】\n林深来了精神，精心照料，进化点一点点攒。小狗也通人性，黏他黏得不行。\n一个月后进化点满了。小狗浑身光芒一闪，体型大了一圈，毛色油亮眼神灵动——进化成了灵犬，能听懂人话，帮他叼东西看家。\n【提示：灵犬可继续进化为哮天犬血脉。】\n林深抱着小狗，忽然觉得自己这落魄的人生，或许要从这只「养不活」的小土狗开始，彻底改变了。"},
 {"cat":"标题简介","genre":"言情","instruction":"为双向暗恋言情起书名并写简介。",
  "output":"【书名】《暗恋三年，原来他也喜欢我》\n【备选】《那杯匿名咖啡，他喝了三年》《便利贴上的双向暗恋》\n【简介】\n林晚暗恋隔壁工位的顾言三年了。她每天偷偷给他带一杯咖啡，贴张便利贴「加油」，却从不敢署名。\n她以为顾言不知道。其实顾言知道，而且他也暗恋她三年了。\n顾言每天假装不经意路过她工位，就为看她一眼。他收到那些匿名咖啡心里甜得不行，却以为是她「顺手」给全组带的，不敢自作多情。\n这天林晚的便利贴不小心写了名字。她发现时咖啡已经送出去了，懊恼得想撞墙——完了，被发现了。\n而顾言看着那张写着「林晚」的便利贴，愣了整整一分钟，然后红了耳根。原来，不是他一个人在自作多情。\n他鼓起勇气，在她咖啡杯下压了张便利贴：「明天的咖啡，我能指定要焦糖味吗？——顾言」"},
 {"cat":"标题简介","genre":"仙侠","instruction":"为风水师仙侠起书名并写简介。",
  "output":"【书名】《风水先生：那枚聚阴钉，是我师兄的手法》\n【备选】《我躲了十年的因果，找上门了》《正心破邪术》\n【简介】\n风水先生陈半仙，被人请去看一处新宅。宅主说自从搬进来，家人接连生病，生意一落千丈。\n陈半仙绕宅走了一圈，罗盘指针疯转。他脸色沉了：「宅主，你这宅子不是风水不好，是被人动了手脚。宅基下埋了东西。」\n挖出来，是一枚聚阴钉——有人故意钉在宅基「气眼」上，把生气转成死气，住久了人财两空。\n宅主又惊又怒：「谁这么害我？！」\n陈半仙没答。他盯着那枚钉子，钉身上刻着一个极淡的标记——那标记他认得，是他那个「死」了十年的师兄的独门手法。\n陈半仙攥紧钉子指尖发凉。师兄没死，而且在害人。他忽然明白，这次看风水，看的不是宅，是一桩他躲了十年的因果。"},
 {"cat":"标题简介","genre":"历史","instruction":"为穿越大宋商人起书名并写简介。",
  "output":"【书名】《大宋：我用会员制开了连锁酒楼》\n【备选】《汴京第一酒楼》《领先古人一千年的经营法》\n【简介】\n穿越到大宋，沈默成了汴京一个小商贩。他一个现代搞商业的，哪看得上这点小打小闹。\n他知道大宋商业繁荣，可经营模式太原始——没有连锁、没有会员、没有营销。这些都是他的机会。\n他盘下一家濒临倒闭的酒楼，做了三件事：会员制充值送菜锁定回头客；连锁统一招牌口味开分店；营销搞限时特惠名人品鉴。\n「沈掌柜这是瞎折腾，酒楼哪有这么多花样？」同行嗤笑。\n可三个月后，沈默的酒楼客似云来，开了五家分店，成了汴京头一份。那些笑他的同行一个个看傻了眼。\n后来同行眼红使坏，挖厨子、造谣、雇人闹事。沈默公开后厨破谣言、给厨子分红稳人心、让口碑说话。\n「做生意拼的是本事和良心。你把心思用在菜上，比用在害我上强。」"},
 {"cat":"标题简介","genre":"科幻","instruction":"为时间循环科幻起书名并写简介。",
  "output":"【书名】《困在同一天，我循环了三百次》\n【备选】《时间循环：我要救那三十七个人》《早上七点，又是这一天》\n【简介】\n早上七点，闹钟响。林原睁开眼，又是这一天——他已经被困在这同一天，循环了三百次。\n他试过一切：上班、逃班、旅行、犯罪、自杀……可第二天早上七点，闹钟照样响，一切重置。\n他快疯了。直到第三百次循环，他注意到一个之前忽略的细节——每天上午十点，市中心那栋楼会塌，死三十七个人。而他每次都在循环重置前「死」于这场塌楼。\n林原忽然明白了。这循环不是无缘无故的。它把他困在这天，是要他「救」那三十七个人。只有救了他们，循环才会结束。\n他看了眼时钟，九点四十。他冲向那栋楼。这一次，他不再想自己怎么活，他要想的，是怎么让那三十七个人，活过十点。"},
 {"cat":"标题简介","genre":"悬疑","instruction":"为调查记者悬疑起书名并写简介。",
  "output":"【书名】《记者：那三十条矿难人命，不能白死》\n【备选】《笔就是他的刀》《被掩盖的矿难》\n【简介】\n记者沈倦收到一封匿名信，说三年前那场「矿难」不是意外，是人祸——矿主为了骗保故意炸了矿井，埋了三十条人命。\n沈倦去调查，可所有人都闭口不言。矿主放话：「谁敢查，就让谁消失。」\n「沈记者，别查了，那矿主背后有人，你惹不起。」老编辑劝。\n沈倦没退。他想起那三十条人命，想起家属至今没拿到的赔偿。他是个记者，笔就是他的刀。\n他暗访取证，终于拿到矿主骗保的证据。可正要发稿时，住处被人翻了个底朝天，证据被抢走了。\n沈倦站在一片狼藉的屋里忽然笑了。他们抢得走证据，抢不走他脑子里的。这一世，他要把这桩被掩盖的人祸，一个字一个字重新写出来，昭告天下。"},
 {"cat":"标题简介","genre":"游戏","instruction":"为抽卡命运游戏起书名并写简介。",
  "output":"【书名】《十连全保底，我抽出了命运之轮》\n【备选】《非酋到极致，触发隐藏卡》《我的卡能逆转命运》\n【简介】\n抽卡仪式，别人十连总能出个稀有卡。轮到林渊，十连抽全是保底——最垃圾的普通卡。\n「哈哈哈，十连全保底！林渊，你这辈子就是个非酋！」满场哄笑。\n林渊没笑。他看着手里十张废卡，忽然其中一张最不起眼的泛起微光：【隐藏卡·命运之轮。非酋到极致方能触发。可逆转一次命运。】\n他试探着催动，卡面光芒一闪：【检测到宿主即将遭遇杀身之祸，是否逆转？】\n林渊还没反应过来，身后传来破空声——有人暗中对他出手。他下意识催动命运之轮，那致命一击竟诡异地偏了。\n林渊攥紧那张卡。别人抽到的是战力，他抽到的，是能改命的神之卡。\n可他不知道，有人要杀他，正是为了夺这张卡。"},
 {"cat":"标题简介","genre":"玄幻","instruction":"为当铺朝奉玄幻起书名并写简介。",
  "output":"【书名】《当铺朝奉：我收的不是当，是因果》\n【备选】《那块玉佩，背着三条人命》《我能看见当品的因果》\n【简介】\n当铺朝奉苏鉴，收了一辈子当品，眼力毒辣。可他有个秘密——他能看出当品里缠着的「因果」。\n这天一个落魄汉子来当一块玉佩。苏鉴一搭眼脸色变了——那玉佩上缠着浓得化不开的血光，是凶物，谁戴谁死。\n「这玉，不收。」苏鉴把玉佩推回去。\n汉子急了：「掌柜，这是祖传的，您行行好……」\n「不是钱的事。」苏鉴压低声音，「这玉上背着三条人命。你戴着它，是不是夜夜噩梦，家人接连出事？」\n汉子浑身一震，扑通跪下：「掌柜神了！求您救我！」\n苏鉴叹了口气。他收的不是当，是因果。这块玉背后的三条人命，是一桩他没躲过的旧案。他知道，从收下这块玉起，他就再也躲不开了。"},
 {"cat":"标题简介","genre":"都市","instruction":"为重生理发师都市起书名并写简介。",
  "output":"【书名】《洗头工出身，我开了网红造型室》\n【备选】《师傅骂我手笨，我靠手艺翻身》《剪出自己的人生》\n【简介】\n2010年，理发店学徒林晚天天被师傅骂「手笨」，只能洗头扫地，摸不到剪刀。\n可她重生了。她记得未来造型师会崛起，有真手艺懂审美的人会赚得盆满钵满。而她前世就是被埋没的手艺人，熬到三十岁还是洗头工。\n这一世她不再傻等师傅教，偷偷练剪练染练造型，把前世记忆里的审美和技法捡起来。\n机会来了——一个挑剔客人对店里所有发型师都不满意。林晚挺身而出：「我来试试。」\n她剪了个前世记忆里的发型，客人照镜子眼睛亮了：「这是我想要的！小姑娘，你手艺比他们强多了！」\n后来她攒钱开了自己的工作室，做定制造型，预约排到三个月后。当初的师傅看着她的店半天说不出话。\n她靠这双手，剪出的不只是发型，是自己的人生。"},
 {"cat":"标题简介","genre":"系统流","instruction":"为开店系统起书名并写简介。",
  "output":"【书名】《我的小面馆，要做百年老店》\n【备选】《别人搞加盟，我偏直营》《开店如做人，稳才是本事》\n【简介】\n林深盘下一家濒临倒闭的小面馆，兜里的钱只够撑一个月。他一个外行，开店纯属赌一把。\n【开店系统绑定。宿主经营可获奖励。】\n他卖出第一碗面，系统提示：【售出一碗面。奖励现金十元，经营经验+1。】\n他兜里真多了十块。林深来了精神，用心做每一碗面，奖励越来越多，店铺一点点升级，解锁神级汤底。\n面馆因为味道好分量足排起长队，一个月后不仅没倒闭还开了分店。\n后来有人找他谈加盟快速扩张，系统弹选项：开放加盟得一百万，直营得神级品控。\n林深选了直营。他记得多少老店毁在加盟品控崩了。\n「开店如做人，快不是本事，稳才是。我要靠这口锅，开出个百年老店。」"},
 {"cat":"标题简介","genre":"言情","instruction":"为娱乐圈报恩言情起书名并写简介。",
  "output":"【书名】《过气后，我资助的贫困生成了大佬》\n【备选】《他回来不是报恩，是为了我》《十年前那笔资助，他记了十年》\n【简介】\n过气女星温念被公司塞去一档恋爱综艺凑数。节目组给她配的「素人男嘉宾」，是个穿着普通、沉默寡言的男人。\n「温姐，委屈你了，配个素人。」导演叹气。\n可录制时她发现这素人不对劲——他随手开的车是限量款；他接的电话对面毕恭毕敬喊他「顾总」；他看她的眼神，像看一个认识很久的人。\n「顾先生，你到底是做什么的？」\n男人笑了：「温小姐，你忘了？十年前你资助过一个贫困生。那个贫困生，现在想回来报恩了。」\n温念愣住。她过气了，他却是隐形大佬，这身份差让她自卑想躲。\n可他说：「我回来不是报恩，是为了你。十年前你是唯一不看轻我穷的人，我记了十年。我喜欢的，是你，不是你的名气。」"},
 {"cat":"标题简介","genre":"仙侠","instruction":"为琴修仙侠起书名并写简介。",
  "output":"【书名】《琴修：我斩的是心魔》\n【备选】《以琴入道》《剑修斩身，我斩心》\n【简介】\n修仙界人人修剑修丹，只有琴修苏弦以琴入道。\n「一个弹琴的，也敢来参加宗门大比？」剑修嗤笑。\n苏弦没争辩。他盘膝坐下抚琴一曲。琴音起，那剑修忽然眼神一滞——他的心魔被琴音勾了出来，整个人陷入幻境地动弹不得。\n苏弦一曲终了，那剑修瘫坐在地冷汗淋漓。\n满场哗然。「这是什么琴？竟能勾人心魔？」\n苏弦收琴平静道：「剑修斩的是身，我琴修斩的是心。心魔不除，修为再高也是走火入魔的命。」\n他看向满场神色复杂的修士：「弹琴的怎么了？今天，我就用这张琴，赢了你们。」"},
 {"cat":"标题简介","genre":"历史","instruction":"为穿越大唐诗人起书名并写简介。",
  "output":"【书名】《大唐：我靠抄诗成名，却心虚了》\n【备选】《我脑子里装着整个盛唐的诗》《不做小偷的诗人》\n【简介】\n穿越到大唐，陈默成了个落魄书生。他不会作诗，可他会「背」——他脑子里装着整个盛唐的诗。\n为了出头，他「抄」了一首李白的诗一举成名。人人赞他「诗才绝世」。\n可陈默心里发虚。他知道这些诗不是他的，他是个「小偷」，偷的是千年后的才华。\n「陈先生，再赋一首！」宴会上众人起哄。\n陈默握着笔手在抖。他忽然觉得自己不能再「抄」了。这些诗是那些诗人的命，他偷来成名是对他们的亵渎。\n他搁下笔深吸一口气：「诸位，陈某今日不赋诗。陈某想说的，是这些诗背后的故事——那些真正写诗的人，他们的苦，他们的志。」\n他决定不再做小偷。他要在这大唐，用自己的方式，留下点真正属于他的东西。"},
]